#!/usr/bin/env python3
"""Patch 004 — index.html: uncropped hero band and heritage photo, complete book cover,
Raffaele's two small photographs in the "Chi vi taglia i capelli" section, canonical/OG/
schema URLs pointing at the live GitHub Pages address. Every replacement must match
exactly once; the result is checked against the sha256 of the reference build."""
import hashlib, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
P = os.path.join(ROOT, 'index.html')
EXPECTED = '65e28b2508e0a4339f38171b2e1abfcd0f793df134752ca24390934be6c3e161'
R = [('.hero-band{margin:0 0 0;position:relative;aspect-ratio:2.2/1;overflow:hidden;border:1px solid var(--rule);border-bottom:0}', '.hero-band{margin:0 0 0;position:relative;aspect-ratio:1.75/1;overflow:hidden;border:1px solid var(--rule);border-bottom:0;background:var(--ink-sunk)}'), ('.hero-band img{width:100%;height:100%;object-fit:cover;object-position:50% 32%}', '.hero-band img{width:100%;height:100%;object-fit:cover;object-position:50% 0}'), ('.hero-band{aspect-ratio:16/10;margin:0 -28px;border-left:0;border-right:0}', '.hero-band{aspect-ratio:1.5/1;margin:0 -28px;border-left:0;border-right:0}'), ('figure.ph img{width:100%;height:auto;border:1px solid var(--rule)}', 'figure.ph img{width:100%;height:auto;display:block;border:1px solid var(--rule)}\n.mini{display:grid;grid-template-columns:1fr 1.8fr;gap:12px;margin-top:14px;align-items:start}\n.mini figcaption{font-size:11.5px;line-height:1.4}\n.mini figcaption b{font-size:11.5px}'), ('.gal img{width:100%;height:100%;object-fit:cover;transition:', '.gal img{width:100%;height:100%;object-fit:cover;object-position:50% 18%;transition:'), ('.feature{position:relative;margin-bottom:56px;border:1px solid var(--rule)}', '.feature{position:relative;margin:0 auto 56px;max-width:1000px;border:1px solid var(--rule)}'), ('.feature img{width:100%;height:auto;max-height:640px;object-fit:cover;object-position:center 35%}', '.feature img{width:100%;height:auto;display:block}'), ('.arch3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:56px}', '.arch3{display:grid;grid-template-columns:1.46fr 1.4fr 1.04fr;gap:18px;margin-top:56px;align-items:start}'), ('      <figure class="ph">\n        <img src="img/salone.jpg" width="1000" height="723" loading="lazy" decoding="async" alt="L\'interno del salone Belli Capelli di Raffaele Russo in via Giuseppe Meda 23 a Milano: specchi, postazioni e lavaggi">\n        <figcaption><b><span data-it>Il salone</span><span data-en>The salon</span></b><span data-it>Via Giuseppe Meda 23 — sei postazioni, un solo maestro.</span><span data-en>Via Giuseppe Meda 23 — six chairs, one master.</span></figcaption>\n      </figure>\n', '      <div>\n        <figure class="ph">\n          <img src="img/salone.jpg" width="1000" height="723" loading="lazy" decoding="async" alt="L\'interno del salone Belli Capelli di Raffaele Russo in via Giuseppe Meda 23 a Milano: specchi, postazioni e lavaggi">\n          <figcaption><b><span data-it>Il salone</span><span data-en>The salon</span></b><span data-it>Via Giuseppe Meda 23 — sei postazioni, un solo maestro.</span><span data-en>Via Giuseppe Meda 23 — six chairs, one master.</span></figcaption>\n        </figure>\n        <div class="mini">\n          <figure class="ph">\n            <img src="img/raffaele.jpg" width="560" height="700" loading="lazy" decoding="async" alt="Raffaele Russo, parrucchiere e maestro d\'arte, nel suo salone Belli Capelli in via Meda 23 a Milano">\n            <figcaption><b>Raffaele Russo</b><span data-it>In salone, 2026.</span><span data-en>In the salon, 2026.</span></figcaption>\n          </figure>\n          <figure class="ph">\n            <img src="img/raffaele-papa-francesco.jpg" width="840" height="580" loading="lazy" decoding="async" alt="Raffaele Russo in abito scuro stringe la mano a Papa Francesco durante un\'udienza">\n            <figcaption><b><span data-it>Con Papa Francesco</span><span data-en>With Pope Francis</span></b><span data-it>Raffaele ricevuto in udienza.</span><span data-en>Raffaele received in audience.</span></figcaption>\n          </figure>\n        </div>\n      </div>\n'), ('<img src="img/vincenzo-premiazione.jpg" width="488" height="252"', '<img src="img/vincenzo-premiazione.jpg" width="536" height="515"'), ('<img src="img/libro-copertina.jpg" width="488" height="325"', '<img src="img/libro-copertina.jpg" width="536" height="793"'), ('"name":"Raffaele Russo","jobTitle":"Parrucchiere e barbiere, maestro d\'arte A.N.A.M.",', '"name":"Raffaele Russo","jobTitle":"Parrucchiere e barbiere, maestro d\'arte A.N.A.M.",\n      "image":"https://www.bellicapellibyrussomilano.it/img/raffaele.jpg",')]
s = open(P, encoding='utf-8').read()
bad = [a[:60] for a, b in R if s.count(a) != 1]
if bad:
    print('PATCH 004: replacement not found exactly once:', bad); sys.exit(1)
for a, b in R:
    s = s.replace(a, b)
s = s.replace('https://www.bellicapellibyrussomilano.it/', 'https://justdirk.github.io/russo/')
s = s.rstrip() + '\n'
open(P, 'w', encoding='utf-8').write(s)
h = hashlib.sha256(s.encode('utf-8')).hexdigest()
print('index.html patched;', 'sha256 OK' if h == EXPECTED else 'sha256 DIFFERS: ' + h)
